INSERT INTO digital_keys(offer_id,code) SELECT o.id,'DEMO-'||o.id||'-'||lpad(n::text,4,'0') FROM offers o CROSS JOIN generate_series(1,15) n ON CONFLICT(code) DO NOTHING;
